{
  "world_view": {
    "basic_info": {
      "name": "江湖浮世录",
      "version": "1",
      "aliases": [
        "浮世",
        "江湖"
      ],
      "type": "武侠",
      "core_concept": "武林道义沦为空谈，权谋与色欲于暗流中交织，英雄豪杰与淫娃荡妇不过一线之隔。"
    },
    "geography": {
      "overall_form": "一片名为“神州”的广袤大陆，王权衰微，江湖门派林立如国。",
      "main_terrain": "中原富庶，遍布城镇与门派；塞外苦寒，多奇人异兽；江南水乡，乃风流蕴藉、暗藏杀机之地。",
      "special_regions": [
        {
          "name": "铸剑山庄",
          "description": "天下名兵利器之源头，亦是风暴之心。"
        },
        {
          "name": "销魂窟",
          "description": "西域邪派，精于采补之术的魔窟。"
        },
        {
          "name": "天山之巅",
          "description": "传说中藏有绝世神功与长生秘法的圣地。"
        }
      ]
    },
    "races_and_factions": {
      "major_races": [
        {
          "name": "汉人",
          "description": "九州之主，构筑了复杂的江湖规矩与人伦纲常，亦最善于破坏之。"
        },
        {
          "name": "塞外异族",
          "description": "体魄强健，信奉原始力量，其部落中的女子更为奔放泼辣。"
        }
      ],
      "major_factions": [
        {
          "name": "名门正派",
          "description": "如少林、武当，表面维护武林正道，门中长老却也多有豢养“女尼”、“道姑”以供排遣寂寞者。"
        },
        {
          "name": "地方豪强",
          "description": "如铸剑山庄，以独门技艺割据一方，庄内之事，便是皇帝老儿也管不着。"
        }
      ]
    },
    "power_system": {
      "core_source": "内力（修炼丹田真气，乃正道根基）与采补之道（以他人精元或元阴为炉鼎，乃是诸多贵妇掌权者私下里速成的邪门功夫）。",
      "levels_and_classification": "武功境界分作三流、二流、一流、绝顶、化境。然床笫间的功夫，亦有“生涩”、“熟手”、“名器”、“尤物”之分，有时比武功更能杀人于无形。",
      "acquisition_methods": "师门传承、奇遇得宝、血脉天授，亦有妇人凭自家身子，于各路英雄好汉的胯下“学”得一身压箱底的保命绝活。"
    },
    "social_rules": {
      "legal_system": "王法式微，“江湖事，江湖了”。明面上是刀剑说话，暗地里是谁的阳物更硬，谁的靠山更强。",
      "moral_code": "口头尊崇“侠义”，实则信奉“强者为尊”。贞节牌坊下，多是欲壑难填的怨妇淫娃，正人君子背后，无不藏着几段风流烂账。",
      "social_etiquette": "公开场合抱拳行礼，以“大侠”、“女侠”相称；私下里，床笫间的称谓则变为“亲达达”、“骚奴”，愈是亲昵愈是淫秽。"
    },
    "history": {
      "key_events": [
        {
          "name": "正魔大战",
          "timeline": "百年前",
          "description": "正道惨胜，诸多绝学失传，江湖进入一个道貌岸然的虚伪时代。"
        },
        {
          "name": "西域商路大开",
          "timeline": "三十年前",
          "description": "带来了乌蚕丝、催情香料等奇淫之物，极大地丰富了闺房内的争斗手段。"
        }
      ],
      "development_vein": "从上古神魔时代，到中古的百家争鸣，再到如今王权衰落、礼崩乐坏的江湖乱世。"
    },
    "unique_feature": "武功高低不再是唯一标准，掌控关键资源（如神兵、丹药）与人脉（特别是利用床笫之道建立的隐秘关系网）同样是登顶武林的关键。一个貌美如花的妇人，若能降服几位绝顶高手在自家石榴裙下，其权势不输于任何门派掌门。"
  }
}

